#pragma once
// Local-only portal retained from the Arduino conference UI. No external assets.
static constexpr char BADGE_PORTAL_HTML[] = R"HTML(<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>init() badge setup</title><style>body{font:17px system-ui;background:#101114;color:#fff;max-width:460px;margin:25px auto;padding:24px}h1{font-size:32px}label{display:block;margin:22px 0 7px}input,button{box-sizing:border-box;width:100%;padding:14px;border-radius:10px;border:1px solid #666;font:inherit}input{background:#24262b;color:#fff}button{margin-top:20px;background:#fff;color:#111;font-weight:650}button.secondary{background:#24262b;color:#fff}p{color:#ccc;line-height:1.5}.row{display:flex;gap:10px;align-items:center}.row input{width:auto}#status{min-height:3em;white-space:pre-wrap}small{color:#bbb}button:disabled{opacity:.5}</style></head><body><p>init() / local badge setup</p><h1>Make it yours.</h1><p>Saved only on this badge. No internet, accounts, or sign-in needed. Blank accounts stay available as placeholders.</p><section aria-labelledby="clockHeading"><h2 id="clockHeading">Clock</h2><p id="clockStatus" role="status" aria-live="polite">Syncing the clock from this browser…</p><button id="clockRetry" type="button" class="secondary">Sync clock again</button><small>Clock updates are kept even if you cancel profile edits. Reopen setup after a timezone or daylight-saving change.</small></section><form id="form"><label for="name">Display name</label><input id="name" maxlength="120" autocomplete="off" value="{{NAME}}"><label for="company">Company (optional)</label><input id="company" maxlength="120" autocomplete="organization" value="{{COMPANY}}"><label for="github">GitHub handle or profile URL</label><input id="github" maxlength="180" autocomplete="off" value="{{GITHUB}}"><label for="x">X / Twitter handle or profile URL</label><input id="x" maxlength="180" autocomplete="off" value="{{X}}"><label for="linkedin">LinkedIn handle or /in/ profile URL</label><input id="linkedin" maxlength="180" autocomplete="off" value="{{LINKEDIN}}"><label for="photo">Your photo</label><input id="photo" type="file" accept="image/jpeg,image/png,image/webp"><p id="photoState">{{PHOTO}}</p><small>Photos are converted on your phone to a JPEG, at most 512 × 512. The badge stores a square crop.</small><label class="row"><input id="remove" type="checkbox">Remove saved photo</label><button id="save" type="submit">Save badge</button><button id="cancel" type="button" class="secondary">Cancel setup</button></form><p id="status" role="status" aria-live="polite"></p><script>'use strict';const nonce='{{NONCE}}';const $=id=>document.getElementById(id);let busy=false;function state(message){$('status').textContent=message}function lock(value){busy=value;$('save').disabled=value;$('cancel').disabled=value;$('clockRetry').disabled=value}async function request(path,body,type='application/json'){const r=await fetch(path,{method:'POST',headers:{'Content-Type':type,'X-Conference-Nonce':nonce},body:type==='application/json'?JSON.stringify(body):body});const result=await r.json();if(!r.ok)throw Error(result.message||'Please try again.');return result}function browserClockPayload(now=new Date()){const payload={epoch:Math.floor(now.getTime()/1000),offset_minutes:-now.getTimezoneOffset()};try{const zone=Intl.DateTimeFormat().resolvedOptions().timeZone;if(typeof zone==='string'&&/^[A-Za-z0-9_+\/-]{1,64}$/.test(zone))payload.timezone=zone}catch{}return payload}async function syncClock(){if(busy)return;lock(true);$('clockStatus').textContent='Syncing the clock from this browser…';try{const result=await request('/clock',browserClockPayload());if(result.ok!==true||result.valid!==true)throw Error(result.message||'Clock verification failed.');$('clockStatus').textContent=result.message||'Clock synchronized.'}catch(error){$('clockStatus').textContent='Clock sync could not be confirmed. '+(error.message||'Check the connection and retry.')}finally{lock(false)}}function decodePhoto(file){return new Promise((resolve,reject)=>{const url=URL.createObjectURL(file),img=new Image();img.onload=()=>{URL.revokeObjectURL(url);resolve(img)};img.onerror=()=>{URL.revokeObjectURL(url);reject(Error('Use a JPEG, PNG, or WebP photo.'))};img.src=url})}function jpegBlob(canvas,quality){return new Promise(resolve=>canvas.toBlob(resolve,'image/jpeg',quality))}async function photo(file){if(file.size>10*1024*1024)throw Error('Choose a photo smaller than 10 MB.');const img=await decodePhoto(file);if(!img.width||!img.height)throw Error('This photo is empty.');const canvas=document.createElement('canvas');const scale=Math.min(1,512/Math.max(img.width,img.height));canvas.width=Math.max(1,Math.round(img.width*scale));canvas.height=Math.max(1,Math.round(img.height*scale));const ctx=canvas.getContext('2d');ctx.fillStyle='#000';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(img,0,0,canvas.width,canvas.height);let blob;for(const quality of [.88,.72,.55,.38]){blob=await jpegBlob(canvas,quality);if(blob&&blob.size<=128*1024)return blob}throw Error('This photo is too detailed. Try a smaller photo.')}function finish(message){state(message);$('form').hidden=true;$('clockRetry').disabled=true} $('photo').addEventListener('change',()=>{if($('photo').files.length){$('remove').checked=false;$('photoState').textContent='New photo selected. Save badge to keep it.'}});$('remove').addEventListener('change',()=>{if($('remove').checked)$('photo').value=''});$('form').addEventListener('submit',async event=>{event.preventDefault();if(busy)return;lock(true);state('Saving…');try{let image=$('remove').checked?'remove':'keep',imageToken='';const file=$('photo').files[0];if(file&&!$('remove').checked){state('Preparing photo on your phone…');const blob=await photo(file);state('Sending photo to your badge…');const result=await request('/image',blob,'image/jpeg');image='staged';imageToken=result.imageToken}const result=await request('/save',{name:$('name').value,company:$('company').value,github:$('github').value,x:$('x').value,linkedin:$('linkedin').value,image,imageToken});finish(result.message)}catch(error){state(error.message+' If the connection was lost, check your badge or reopen setup to confirm what was saved.');lock(false)}});$('cancel').addEventListener('click',async()=>{if(busy)return;lock(true);try{const result=await request('/cancel',{});finish(result.message)}catch(error){state(error.message+' You can also press either badge pusher to leave setup.');lock(false)}});$('clockRetry').addEventListener('click',syncClock);void syncClock();</script></body></html>)HTML";
